<!DOCTYPE html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mi carrito | EcoEntrega</title><style>*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#f7faf8;color:#1c1917}header{background:#064e3b;color:#fff;padding:17px 7%;display:flex;justify-content:space-between;align-items:center}header a{color:#fff;text-decoration:none;font-weight:bold}.content{max-width:950px;margin:42px auto;padding:0 20px}.box{background:#fff;border-radius:18px;padding:26px;box-shadow:0 8px 30px #0001}.row{display:flex;justify-content:space-between;gap:20px;align-items:center;padding:18px 0;border-bottom:1px solid #e7e5e4}.row:last-of-type{border:0}.row h3{margin:0 0 5px}.row p{margin:0;color:#57534e}.remove{border:1px solid #dc2626;background:#fff;color:#b91c1c;padding:8px 11px;border-radius:8px;cursor:pointer}.total{margin-top:20px;padding-top:20px;border-top:2px solid #d1fae5;display:flex;justify-content:space-between;font-size:21px;font-weight:bold;color:#065f46}.empty{text-align:center;padding:45px;color:#57534e}.link{display:inline-block;margin-top:20px;padding:12px 16px;border-radius:10px;background:#047857;color:#fff;text-decoration:none;font-weight:bold}.notice{color:#047857;font-weight:bold}@media(max-width:550px){.row{align-items:flex-start;flex-direction:column}}</style></head><body><header><a href="{{ route('home') }}">♻ EcoEntrega</a><a href="{{ route('account') }}">Mi cuenta</a></header><main class="content"><h1>Mi carrito</h1>@if(session('success'))<p class="notice">{{ session('success') }}</p>@endif<div class="box">@forelse($details as $detail)<div class="row"><div><h3>{{ $detail->product->product_name }}</h3><p>Cantidad: {{ $detail->quantity }} · ${{ number_format($detail->product->price, 0, ',', '.') }} c/u</p></div><div><strong>${{ number_format($detail->subtotal, 0, ',', '.') }}</strong><form method="POST" action="{{ route('cart.remove', $detail->id_cart_detail) }}" style="margin-top:10